#!/usr/bin/env node
/**
 * Reads `data/wordBlocklist.txt` (the single source of truth) and writes the two
 * generated files the generator uses:
 *
 *   data/wordBlocklist.ts      — the runtime gate, imported by utils/wordQuality.ts
 *   data/commonCrosswordGlue.ts — the curated pool for 2- and 3-letter slots
 *
 *   node scripts/build-common-glue.cjs
 *   node scripts/build-common-glue.cjs --dry
 *
 * Why a shared pool for short slots: Persian has very few thematic two-letter
 * words, so a category grid can never fill its ~12 two-letter slots from its own
 * vocabulary. That fallback used to be "every short word in the game", which is
 * how «وب», «شی» and «مخ» landed in food and history grids. The pool is now
 * harvested from what already exists, minus everything the blocklist rejects.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const ZWNJ = /‌/g;
const norm = (s) => s.toUpperCase().replace(ZWNJ, '').replace(/[\s-]/g, '');
const letters = (s) => s.replace(ZWNJ, '').length;

// ---------------------------------------------------------------- blocklist
const raw = fs.readFileSync(path.join(ROOT, 'data/wordBlocklist.txt'), 'utf8');
const sections = {};
let current = null;
for (const line of raw.split(/\r?\n/)) {
  const t = line.trim();
  if (!t || t.startsWith('#')) continue;
  const m = t.match(/^\[([a-z:]+)\]$/);
  if (m) { current = m[1]; sections[current] = []; continue; }
  if (!current) continue;
  sections[current].push(t);
}
const never = [...new Set(sections.never || [])];
const locked = Object.entries(sections)
  .filter(([k]) => k !== 'never')
  .map(([k, v]) => [k.replace(/:only$/, ''), [...new Set(v)]]);

const tsList = (arr, indent = '  ') =>
  arr.map((w) => `${indent}${JSON.stringify(w)},`).join('\n');

const blocklistTs = `/**
 * Generated by \`scripts/build-common-glue.cjs\` — do not edit.
 * Source of truth: \`data/wordBlocklist.txt\`.
 */
export const NEVER_FA: readonly string[] = [
${tsList(never)}
];

export const CATEGORY_LOCKED_FA: readonly [string, readonly string[]][] = [
${locked.map(([c, ws]) => `  [${JSON.stringify(c)}, [${ws.map((w) => JSON.stringify(w)).join(', ')}]]`).join(',\n')}
];
`;
const glueTsPath = path.join(ROOT, 'data/commonCrosswordGlue.ts');
const blockTsPath = path.join(ROOT, 'data/wordBlocklist.ts');

// ---------------------------------------------------------------- pool harvest
function loadCorpus() {
  const out = new Map();
  for (const f of ['glue_dictionary.json', 'dictionary.json']) {
    const p = path.join(ROOT, 'server/local-data', f);
    if (!fs.existsSync(p)) continue;
    for (const e of JSON.parse(fs.readFileSync(p, 'utf8'))) {
      if (e.language && e.language !== 'fa') continue;
      if (!e.word || !e.clue) continue;
      if (!out.has(e.word)) out.set(e.word, e);
    }
  }
  return out;
}

const denySet = new Set(never.map(norm));
// A word that is only legitimate inside one category must not become the
// filler for everybody else's grid.
const lockSet = new Set(locked.flatMap(([, ws]) => ws.map(norm)));
const all = loadCorpus();
const kept = [];
const dropped = [];

for (const e of all.values()) {
  const L = letters(e.word);
  if (L < 2 || L > 3) continue;
  const reject = (why) => dropped.push(`${e.word} (${why})`);
  if (denySet.has(norm(e.word))) reject('blocklist');
  else if (lockSet.has(norm(e.word))) reject('category-locked');
  else if (!/^[؀-ۿ]+$/.test(e.word.replace(ZWNJ, ''))) reject('non-Persian');
  else if (/[۰-۹0-9]/.test(e.word)) reject('digit in word');
  else if (/[A-Za-z0-9]/.test(e.clue)) reject('latin in clue');
  else if (e.clue.length < 6 || e.clue.length > 70) reject(`clue length ${e.clue.length}`);
  else if (norm(e.clue).includes(norm(e.word))) reject('answer in clue');
  else kept.push(e);
}

kept.sort((a, b) => letters(a.word) - letters(b.word) || a.word.localeCompare(b.word, 'fa'));
const byLen = {};
for (const e of kept) byLen[letters(e.word)] = (byLen[letters(e.word)] || 0) + 1;

console.log(`blocklist   : ${never.length} never-forms, ${locked.length} category locks`);
console.log(`short pool  : ${kept.length} kept (${Object.entries(byLen).map(([k, v]) => `L${k}:${v}`).join(' ')}) · ${dropped.length} dropped`);

if (process.argv.includes('--dry')) process.exit(0);

fs.writeFileSync(blockTsPath, blocklistTs);
console.log(`wrote       : data/wordBlocklist.ts`);

fs.writeFileSync(glueTsPath, `/**
 * COMMON_CROSSWORD_GLUE_FA — curated pool for two- and three-letter slots.
 *
 * Generated by \`scripts/build-common-glue.cjs\` from the words the game already
 * has, minus \`data/wordBlocklist.txt\`. Regenerate instead of editing by hand:
 *
 *   node scripts/build-common-glue.cjs
 */
import { DictionaryEntry } from '../types';

export const COMMON_CROSSWORD_GLUE_FA: DictionaryEntry[] = [
${kept.map((e) => `  { word: ${JSON.stringify(e.word)}, clue: ${JSON.stringify(e.clue)}, category: 'general', language: 'fa' },`).join('\n')}
];
`);
console.log(`wrote       : data/commonCrosswordGlue.ts (${kept.length} entries)`);
